def chebyshev_polynomial_t_func(x, n):
    """Chebyshev polynomial of the first kind T_n(x).

    Uses the 3-term recurrence that is valid for ALL real x:
        T_0(x) = 1
        T_1(x) = x
        T_n(x) = 2*x*T_{n-1}(x) - T_{n-2}(x)   for n >= 2
    """
