    n_i32 = n.to(tl.int32)

    # T_0(x) = 1
    t0 = 1.0 + 0.0 * x_f32  # broadcast 1.0 to shape
    # T_1(x) = x
    t1 = x_f32

    result = t0
    result = tl.where(n_i32 == 1, t1, result)

    # Compute T_k for k >= 2 using recurrence
    t_km2 = t0
    t_km1 = t1
    for k in tl.static_range(2, _MAX_POLY_DEGREE):
        t_k = 2.0 * x_f32 * t_km1 - t_km2
        result = tl.where(n_i32 == k, t_k, result)
        t_km2 = t_km1
        t_km1 = t_k

    return result


